return ['domain'=>'zinn-order-updates','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-order-updates','pot-creation-date'=>'2026-11-08T13:09:49+00:00','po-revision-date'=>'2026-11-08T13:09:49+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Order Updates'=>'Zinn® Order Updates','https://zinndigital.com/wordpress-plugins/zinn-order-updates'=>'https://zinndigital.com/wordpress-plugins/zinn-order-updates','SMS and WhatsApp order updates for your store, sent through Zinn® Campaigns under your store\'s own name. Connect in one click; no keys to paste.'=>'Ažuriranja narudžbi putem SMS-a i WhatsAppa za vašu trgovinu, poslana putem usluge Zinn® Campaigns pod vlastitim nazivom vaše trgovine. Povežite se jednim klikom; nema ključeva za lijepljenje.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Order Updates'=>'Ažuriranja narudžbe','Your store is connected to Zinn® Campaigns.'=>'Vaša je trgovina povezana sa Zinn® Campaigns.','Your store is disconnected. No messages will be sent.'=>'Vaša trgovina je odspojena. Poruke se neće slati.','That connection took too long or was started in another browser. Press Connect again.'=>'To povezivanje trajalo je predugo ili je pokrenuto u drugom pregledniku. Pritisnite ponovno Poveži.','Zinn® did not accept the connection. Press Connect again; if it keeps failing, contact Zinn® support.'=>'Zinn® nije prihvatio povezivanje. Pritisnite ponovno „Poveži se”; ako se problem nastavi, obratite se podršci za Zinn®.','Your site could not reach Zinn®. Check that your host allows outgoing connections, then press Connect again.'=>'Vaše web-mjesto nije moglo doći do Zinn®. Provjerite dopušta li vaš poslužitelj odlazne veze, a zatim ponovno pritisnite „Poveži se”.','Send your customers SMS and WhatsApp updates about their orders, under your store\'s own name, paid from your Zinn® credit.'=>'Šaljite svojim kupcima ažuriranja o njihovim narudžbama putem SMS-a i WhatsApp-a, pod nazivom vlastite trgovine, plaćena iz vašeg Zinn® kredita.','Connect opens Zinn® in this window. Sign in or create an account, approve this store, and you come straight back here. You never paste a key.'=>'Poveži otvara Zinn® u ovom prozoru. Prijavite se ili stvorite račun, odobrite ovu trgovinu i vratit ćete se izravno ovamo. Nikada ne lijepite ključ.','Connect to Zinn® Campaigns'=>'Povežite se sa Zinn® Campaigns','Connected, but Zinn® could not be reached just now. We will try again shortly.'=>'Povezano, ali se s uslugom Zinn® trenutačno nije moglo stupiti u kontakt. Pokušat ćemo ponovno uskoro.','Store'=>'Trgovina','Connected'=>'Povezano','Zinn® Campaigns'=>'Zinn® Campaigns','Open for your account'=>'Otvoreno za vaš račun','Not open for your account yet. Zinn® will e-mail you when it is.'=>'Još nije otvoreno za Vaš račun. Zinn® će Vam poslati e-poštu kada bude dostupno.','Disconnect'=>'Prekini vezu','You are not allowed to connect this store.'=>'Nemate dopuštenje za povezivanje ove trgovine.','You are not allowed to disconnect this store.'=>'Nemate dopuštenje za prekidanje veze s ovom trgovinom.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički priručnici','Read the %s user guide'=>'Pročitajte korisnički vodič za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® smještaj za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, svakodnevne sigurnosne kopije, besplatna migracija i upravljačka ploča stvorena za osobe koje vode više od jednog web-mjesta.','The Zinn® marketplace'=>'Tržište Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte etablirane web-stranice, domene i plasmane poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — angažirajte ljude koji se time profesionalno bave','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih profesionalaca: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i omogućite im davanje ponuda.','See the Zinn Digital® release notes.'=>'Pogledajte napomene o izdanju za Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usluga ažuriranja za Zinn® nije izdala poveznicu za preuzimanje ovog ažuriranja. Provjerite može li ovo web-mjesto pristupiti platformi Zinn®, a zatim pokušajte ponovno.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ažuriranje se nije moglo preuzeti s usluge ažuriranja Zinn® (%s). Pokušajte ponovno za nekoliko minuta.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.']];